class Solution {
public:
    vector<int> toggleLightBulbs(vector<int>& bulbs) {
        bool on[101] = {false};
        for (int b : bulbs) on[b] = !on[b];
        vector<int> res;
        for (int i = 1; i <= 100; i++) if (on[i]) res.push_back(i);
        return res;
    }
};

