var toggleLightBulbs = function(bulbs) {
    const cnt = {};
    for (const b of bulbs) cnt[b] = (cnt[b] || 0) + 1;
    return Object.keys(cnt).map(Number).filter(v => cnt[v] % 2 === 1).sort((a, b) => a - b);
